// NoCrash silent-failure watchdog.
// Flags two things a green checkmark hides:
//   1. a run that never fired (missed run)
//   2. a run that finished green but moved nothing (ran but did nothing)

const GRACE = 1.2; // flag a missed run once it is 20% past its expected interval
const now = Date.now();
const norm = (s) => String(s || '').trim().toLowerCase();

const watchlist = ($('Which workflows to watch').first().json.watchlist) || [];
const workflows = $('List your workflows').all().map((i) => i.json);
const runs = $('Recent runs').all().map((i) => i.json);

// How many items did the final node of this execution actually emit?
function itemsProduced(run) {
  const rd = run && run.data && run.data.resultData;
  if (!rd || !rd.runData) return null; // detail not included -> unknown, do not guess
  const lastName = rd.lastNodeExecuted;
  const last = lastName && rd.runData[lastName] && rd.runData[lastName][0];
  const main = last && last.data && last.data.main;
  if (!Array.isArray(main)) return null;
  return main.reduce((sum, out) => sum + (Array.isArray(out) ? out.length : 0), 0);
}

const flags = [];

for (const watch of watchlist) {
  const name = watch.name;
  const everyMin = Number(watch.expectedEveryMinutes) || 0;
  const minItems = watch.minItems == null ? 1 : Number(watch.minItems);

  const wf = workflows.find((w) => norm(w.name) === norm(name));
  if (!wf) {
    flags.push({ workflow: name, check: 'not found', detail: 'No workflow named "' + name + '" in your n8n. Check the spelling in the step above.' });
    continue;
  }

  const wfRuns = runs
    .filter((r) => String(r.workflowId) === String(wf.id))
    .sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt));
  const successes = wfRuns.filter((r) => r.status === 'success');
  const lastSuccess = successes[0];

  // Check 1: the run that never fired.
  if (everyMin > 0) {
    if (!lastSuccess) {
      flags.push({ workflow: name, check: 'missed run', detail: 'No good run on record yet. You expect one about every ' + everyMin + ' min.' });
    } else {
      const lastMs = new Date(lastSuccess.stoppedAt || lastSuccess.startedAt).getTime();
      const overdueMin = Math.round((now - lastMs) / 60000);
      if (now - lastMs > everyMin * 60000 * GRACE) {
        flags.push({ workflow: name, check: 'missed run', detail: 'Last good run was ' + overdueMin + ' min ago; you expect one about every ' + everyMin + ' min.', lastSuccessAt: new Date(lastMs).toISOString(), overdueMinutes: overdueMin });
      }
    }
  }

  // Check 2: green but empty.
  for (const r of successes.slice(0, 20)) {
    const produced = itemsProduced(r);
    if (produced !== null && produced < minItems) {
      flags.push({ workflow: name, check: 'ran but did nothing', detail: 'A run finished green but moved ' + produced + ' item(s); you expect at least ' + minItems + '.', when: r.stoppedAt || r.startedAt, itemsProduced: produced });
      break; // one example per workflow is plenty
    }
  }
}

const lines = flags.map((f) => '- *' + f.workflow + '* - ' + f.check + ': ' + f.detail);
const message = flags.length
  ? ':rotating_light: NoCrash caught ' + flags.length + ' thing(s) worth a look:\n' + lines.join('\n') + "\n\nThis is a check you run yourself. NoCrash watches from outside your instance, learns each workflow's normal cadence, and keeps watching even when your instance is down. Score a workflow free, no signup: https://nocrash.io/tools/n8n-workflow-grader?utm_source=n8n-templates&utm_medium=community&utm_campaign=node-launch-2026"
  : '';

return [{ json: { flaggedCount: flags.length, flags, message } }];
